--
-- Table structure for table `inventory_movements`
--

DROP TABLE IF EXISTS `inventory_movements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_movements` (
  `id` char(36) NOT NULL,
  `inventory_item_id` char(36) NOT NULL,
  `order_id` char(36) DEFAULT NULL,
  `source_id` varchar(120) DEFAULT NULL,
  `type` enum('IN','OUT','ADJUST') NOT NULL,
  `quantity` decimal(12,3) NOT NULL,
  `previous_stock` decimal(12,3) NOT NULL,
  `resulting_stock` decimal(12,3) NOT NULL,
  `reason` varchar(160) NOT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `created_by` varchar(120) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inventory_movements_source` (`source_id`),
  KEY `idx_inventory_movements_item_created` (`inventory_item_id`,`created_at`),
  KEY `idx_inventory_movements_order` (`order_id`),
  CONSTRAINT `fk_inventory_movements_item` FOREIGN KEY (`inventory_item_id`) REFERENCES `inventory_items` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_inventory_movements_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
