  `display_number` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `status` enum('NEW','CONFIRMED','PREPARING','READY','OUT_FOR_DELIVERY','COMPLETED','CANCELED') NOT NULL DEFAULT 'NEW',
  `fulfillment_type` enum('PICKUP','DELIVERY') NOT NULL,
  `customer_name` varchar(120) NOT NULL,
  `customer_phone` varchar(30) NOT NULL,
  `notes` text DEFAULT NULL,
  `street` varchar(180) DEFAULT NULL,
  `number` varchar(30) DEFAULT NULL,
  `complement` varchar(120) DEFAULT NULL,
  `neighborhood` varchar(120) DEFAULT NULL,
  `city` varchar(120) DEFAULT NULL,
  `state` char(2) DEFAULT NULL,
  `postal_code` varchar(12) DEFAULT NULL,
  `address_reference` varchar(255) DEFAULT NULL,
  `subtotal` decimal(10,2) NOT NULL,
  `delivery_fee` decimal(10,2) NOT NULL DEFAULT 0.00,
  `digital_security_fee` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total` decimal(10,2) NOT NULL,
  `payment_method` enum('PIX','CASH','CREDIT_CARD','DEBIT_CARD','ONLINE') DEFAULT NULL,
  `payment_status` enum('NOT_REQUIRED','PENDING','APPROVED','REJECTED','EXPIRED') NOT NULL DEFAULT 'NOT_REQUIRED',
  `payment_provider` varchar(40) DEFAULT NULL,
  `payment_external_id` varchar(100) DEFAULT NULL,
  `payment_expires_at` datetime(3) DEFAULT NULL,
  `pix_copy_paste` text DEFAULT NULL,
  `pix_qr_code_base64` longtext DEFAULT NULL,
  `payment_checkout_url` text DEFAULT NULL,
  `paid_at` datetime(3) DEFAULT NULL,
  `change_for` decimal(10,2) DEFAULT NULL,
  `coupon_code` varchar(50) DEFAULT NULL,
  `discount_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `completed_at` datetime(3) DEFAULT NULL,
  `cancellation_reason` varchar(255) DEFAULT NULL,
  `inventory_processed_at` datetime(3) DEFAULT NULL,
  `inventory_reverted_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `customer_email` varchar(254) DEFAULT NULL,
  `customer_document` varchar(14) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_orders_display_number` (`display_number`),
  UNIQUE KEY `payment_external_id` (`payment_external_id`),
  KEY `idx_orders_status_created_at` (`status`,`created_at`),
  KEY `idx_orders_customer_phone` (`customer_phone`),
  KEY `idx_orders_customer_created` (`customer_phone`,`created_at`),
  KEY `idx_orders_payment_expiration` (`payment_status`,`payment_method`,`created_at`),
  KEY `idx_orders_created` (`created_at`),
  CONSTRAINT `chk_orders_values` CHECK (`subtotal` >= 0 and `delivery_fee` >= 0 and `total` >= 0),
  CONSTRAINT `chk_orders_delivery_address` CHECK (`fulfillment_type` = 'PICKUP' or `street` is not null and `number` is not null and `neighborhood` is not null and `city` is not null and `state` is not null),
  CONSTRAINT `chk_orders_total` CHECK (`total` = `subtotal` + `delivery_fee` + `digital_security_fee` - `discount_amount`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
